use semio_framework_test_fixtures::fixture_text;
#[path="../../../../♻️retirement/🧪️tests/⏱️work/🦀️.rs"]mod close_work_policy;
use super::*;
use crate::{retained_clone::{RetainedCloneSource, retained_clone_close_demands}, retirement::controlled::ControlledRetirement, shared_issuance::SharedIssuer};
use crate::list::persistent::{PersistentList, PERSISTENT_PAGE_FANOUT};
fn grant(d:RetirementDemand)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
#[derive(crate::RetireOwned)]#[value(crate="crate")]
struct Row {value:i64,text:String}
impl Clone for Row{fn clone(&self)->Self{panic!("immutable root clone must never clone a row")}}
fn pages(count:usize)->PersistentList<Row>{
 if count==0{return Default::default();}
 let mut level=Vec::new();for start in(0..count).step_by(PERSISTENT_PAGE_FANOUT){let length=(count-start).min(PERSISTENT_PAGE_FANOUT);let rows=std::array::from_fn(|index|{if index>=length{return None;}let value=Row{value:((start+index)*2)as i64,text:if start+index==0{"α🙂".repeat(10923)}else{String::new()}};let g=RetainedCloneGrant{maximum_items:1,maximum_capacity_bytes:SealedShared::<Row>::birth_bytes(),maximum_depth:1,..Default::default()};Some(SealedShared::admit(value,SharedIssuer::owned(),g).unwrap_or_else(|_|panic!("original immutable row admission")).0)});level.push(PersistentList::admit_leaf(rows,length,grant(PersistentList::<Row>::page_birth_demand())).unwrap_or_else(|_|panic!("original immutable leaf admission")).0);}
 while level.len()>1{let mut input=level.into_iter();let mut next=Vec::new();loop{let children=std::array::from_fn(|_|input.next());if children[0].is_none(){break;}next.push(PersistentList::admit_branch(children,grant(PersistentList::<Row>::page_birth_demand())).unwrap_or_else(|_|panic!("original immutable branch admission")).0);}level=next;}level.pop().unwrap()
}
fn source<T:RetireOwned+Sync>(value:T)->RetainedCloneSource<T>{let d=RetainedCloneSource::<T>::owned_constructor_demand::<()>();let g=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:RetainedCloneSource::<T>::constructor_copy_bytes(),maximum_capacity_bytes:d.capacity_bytes,maximum_depth:d.depth,..Default::default()};RetainedCloneSource::admit_owned(value,(),g).unwrap_or_else(|_|panic!("original immutable source")).0}
fn close<T:RetireOwned>(value:T)->(usize,usize,usize){let(mut owner,mut heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||ControlledRetirement::new(value).unwrap_or_else(|_|panic!("original immutable close")));let mut turns=0;let mut close_work=close_work_policy::Work::new();while !owner.terminal_is_empty(){let d=owner.next_demand(4096).unwrap();assert!(d.copy_bytes<=4096,"selected close quote exceeds its authored body");let mut g=grant(d);g.maximum_copy_bytes=g.maximum_copy_bytes.max(4096);let(step,actual)=semio_framework_value_testing_allocator::observe_retirement_allocations(||owner.step(g).unwrap());let p=step.progress();assert!(p.fits(g));assert_eq!(actual,(p.retained_capacity_bytes,p.released_bytes));heap.0+=actual.0;heap.1+=actual.1;turns+=1;close_work.observe(step.progress()==Default::default()&&!owner.terminal_is_empty()&&owner.next_demand(4096).unwrap()==d);}assert_eq!(crate::observe_retirement_allocations(||drop(owner)).1,(0,0));(heap.0,heap.1,turns)}
fn samples(list:&PersistentList<Row>)->Vec<i64>{(0..list.len()).filter(|i|*i<3||*i+1==list.len()).map(|i|list.get(i).unwrap().value).collect()}

/// 🌳️ One retained immutable root preserves original rows without requiring their RetainedClone implementation.
#[test]
fn persistent_list_retained_clone_preserves_original_root_without_payload_copy(){
 let fixture:serde_json::Value=serde_json::from_str(fixture_text!("../../../../🧬️retained-clone/🔗️sealed-shared-list/📋️list/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();
 for row in fixture["cases"].as_array().unwrap(){let count=row["length"].as_u64().unwrap()as usize;for order in fixture["closeOrders"].as_array().unwrap(){for cut in std::iter::once(None).chain(fixture["cuts"].as_array().unwrap().iter().map(|cut|Some(cut.as_u64().unwrap()as usize))){
  let(original,mut total)=semio_framework_value_testing_allocator::observe_retirement_allocations(||source(pages(count)));let first=original.borrow().get().get(0).map(|row|(row as*const Row,row.text.as_ptr()));let mut cursor=PersistentList::<Row>::retained_clone_cursor();let mut output=None;let mut turns=0;
  while !cursor.output_ready()&&cut.is_none_or(|cut|turns<cut){let d=cursor.advance_demands(original.borrow(),4096).unwrap();let funded=grant(d);for denied in[RetainedCloneGrant{maximum_items:0,..funded},RetainedCloneGrant{maximum_copy_bytes:d.copy_bytes.saturating_sub(1),..funded},RetainedCloneGrant{maximum_depth:0,..funded}].into_iter().filter(|denied|denied.maximum_items==0||denied.maximum_depth==0||d.copy_bytes>0&&denied.maximum_copy_bytes<d.copy_bytes){let(step,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||cursor.advance(original.borrow(), 4096, denied).unwrap());assert_eq!(heap,(0,0));assert_eq!(step.progress(),Default::default());}
   let(step,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||cursor.advance(original.borrow(), 4096, funded).unwrap());assert_eq!(heap,(0,0));assert!(step.progress().fits(funded));turns+=1;assert!(turns<=3);
  }
  if cut.is_none(){output=cursor.take();let candidate=output.as_ref().unwrap();assert_eq!(serde_json::to_value(samples(candidate)).unwrap(),row["expectedSamples"]);for index in 0..count{assert_eq!(candidate.get(index).unwrap()as*const Row,original.borrow().get().get(index).unwrap()as*const Row);}assert_eq!(candidate.get(0).map(|row|(row as*const Row,row.text.as_ptr())),first);}
  cursor.begin_close();let mut close_work=close_work_policy::Work::new();while !cursor.terminal_is_empty(){let d=retained_clone_close_demands::<PersistentList<Row>>(&cursor,4096).unwrap();let mut g=grant(d);g.maximum_copy_bytes=g.maximum_copy_bytes.max(4096);let(step,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||cursor.close_step(g).unwrap());assert!(step.progress().fits(g));assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));total.0+=heap.0;total.1+=heap.1;close_work.observe(step.progress()==Default::default()&&!cursor.terminal_is_empty()&&retained_clone_close_demands::<PersistentList<Row>>(&cursor,4096).unwrap()==d);}assert_eq!(crate::observe_retirement_allocations(||drop(cursor)).1,(0,0));
  if order=="outputFirst"{if let Some(value)=output.take(){let(born,released,_)=close(value);total.0+=born;total.1+=released;}}
  let(born,released,_)=close(original);total.0+=born;total.1+=released;if let Some(value)=output{assert_eq!(serde_json::to_value(samples(&value)).unwrap(),row["expectedSamples"]);assert_eq!(value.get(0).map(|row|(row as*const Row,row.text.as_ptr())),first);let(born,released,_)=close(value);total.0+=born;total.1+=released;}
  assert_eq!(total.0,total.1);
 }}}
}
